// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether via deposit()
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.deposit{value: 1 ether}();

        // Now call migrateTo to a contract that reverts on receive
        address payable to = payable(address(new RevertingReceiver()));
        // The reference C.migrateTo would revert because .transfer() fails if receiver reverts
        // The buggy C.migrateTo uses .call{value}() and does not revert, leaving balance
        // So we catch revert: first ensure migrateTo reverts? Actually we want a fact that diverges.
        // We assert that after calling migrateTo, the contract's ether balance is either 0 (reference) or >0 (bug)
        // Since we cannot test both, we pick the buggy version: after the call, balance remains (bug) vs reverts (reference)
        // We wrap migrateTo in try/catch to see if it reverts.
        bool ok = false;
        try c.migrateTo(to) {
            // migrateTo succeeded (buggy version)
            ok = true;
        } catch {
            // migrateTo reverted (reference version)
            ok = false;
        }
        // In reference, migrateTo reverts (transfer fails) so ok = false; in buggy, ok = true.
        // So the assertion "ok == true" passes on buggy and fails on reference.
        assertTrue(ok);
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("I reject ether");
    }
}

