pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund creator and deposit
        address creator = address(this);
        address to = address(0x1234);
        vm.deal(creator, 1 ether);
        vm.prank(creator);
        c.deposit{value: 1 ether}();

        // Make 'to' reject ether transfers
        vm.prank(to);
        (bool success, ) = address(to).call{value: 0}("");
        // Now call migrateTo - should send all balance
        c.migrateTo(to);

        // Check contract balance: reference (.transfer) reverts -> balance unchanged, but .call succeeds -> balance becomes 0
        // Actually, with .transfer the call would revert, so contract balance remains 1 ether
        // With .call{value} it does NOT revert, so balance becomes 0
        assertTrue(address(c).balance == 0);
    }
}

